-- Attestation style calibration 2026-10-20: 12 original REVIEW pedagogy candidates.
-- Style inspiration only from Drive 2024/25/26 historic pedagogy collections; authoritative content = canonical M14-M16 + official 2026 exam specification.
-- Idempotent source-reference guard. No learner publication, previous question mutation, or invented editorial attestations.
BEGIN;
DO $calibrate$
DECLARE v jsonb; v_q uuid; v_o uuid; v_ids uuid[]; v_payload jsonb; v_pairs jsonb; v_subject uuid; v_construct uuid; v_lesson uuid; v_group text; v_ref text; v_type text; i integer; j integer;
BEGIN
 SELECT id INTO STRICT v_subject FROM public.subjects WHERE code='informatika';
 FOR v IN SELECT value FROM jsonb_array_elements($bank$[{"c":"KS.01","type":"Y1","k":"mulohaza","d":4,"s":"8-sinfda kod yozish bo‘yicha nazoratda sinfning uchdan biri shart operatorini bemalol qo‘lladi, boshqalari esa misolni boshlashda qiynaldi. O‘qituvchi keyingi dars rejasini qanday o‘zgartirsa, baholash dalillaridan eng samarali foydalangan bo‘ladi?","o":["Sinf uchun avvalgi reja sur’atini saqlab, mavzuni yakuniy testga qoldirish","O‘zlashtirish guruhlariga mos tayanch va kengaytiruvchi mashqlarni rejalash","Yangi mavzuga o‘tib, qiyinchilikni keyingi oylik baholashda aniqlash","Hamma uchun nazariy izohni ko‘paytirib, baholash natijalarini keyin taqqoslash"],"a":1,"e":"Reja o‘quvchilarning o‘zlashtirish darajasi va aniq ehtiyojlariga moslashtiriladi."},{"c":"KS.05","type":"Y1","k":"mulohaza","d":4,"s":"Yangi o‘quvchi ko‘rsatmalarni o‘qitish tilida sekin tushunadi. Guruhli ishda sinfdoshlari unga fikr bildirish uchun yetarli vaqt bermayapti. O‘qituvchi fan maqsadini saqlab, sinfdagi barcha bolalarning xavfsiz va teng ishtirokini ta’minlamoqchi. Qanday yondashuv asosli?","o":["Bola uchun barcha mashqlarni sinfdoshlariga bajarib berishni vaqtincha topshirish","Mos tayanch ko‘rsatma berib, mustaqil ishtirok va o‘zaro hurmatni ta’minlash","O‘quvchini muhokamadan olib, keyingi chorakda qayta qo‘shishga qaror qilish","Bir xil murakkab topshiriqni saqlab, yordamni faqat yakuniy bahodan keyin ko‘rsatish"],"a":1,"e":"Inklyuziv yondashuv maqsadni saqlaydi va ehtiyojga mos yordam orqali teng qatnashish imkonini beradi."},{"c":"PM.GEN.01","type":"Y1","k":"mulohaza","d":4,"s":"Tabiatshunoslik darsida o‘quvchilar uchta turli materialning qizdirilganda kengayganini tajribada ko‘rdi. O‘qituvchi shu kuzatuvlar asosida umumiy taxminni shakllantirishni va uni boshqa materialda sinashni so‘radi. Bu fikrlash yo‘li qanday xususiyati bilan ajraladi?","o":["Tayyor umumiy qoidadan bittagina hodisa uchun aniq natija chiqariladi","Alohida kuzatuvlardan umumiy xulosa chiqarilib, keyingi dalil bilan tekshiriladi","Ikki predmetdagi o‘xshashlikdan boshqa xususiyat uchun taxmin qilinadi","Oldindan berilgan ta’rifga misollar topilib, kuzatishlar chetga suriladi"],"a":1,"e":"Induksiya xususiy faktlardan umumiy fikrga o‘tishdir; yangi tajriba bilan tekshirish xulosaning asosini mustahkamlaydi."},{"c":"PM.GEN.06","type":"Y1","k":"mulohaza","d":4,"s":"O‘quvchi o‘qituvchi doskada ko‘rsatgan yechimda xato borligini odob bilan bildirdi. O‘qituvchi javobni tekshirganida e’tiroz haq ekanini payqadi. Pedagogik takt, o‘qituvchi obro‘si va sinfda o‘zaro hurmat tamoyilini hisobga olganda eng maqbul munosabat qaysi?","o":["O‘quvchining dalilini tan olib, xatoni xotirjam tuzatib, fikrini qadrlash","O‘qituvchining mavqeini saqlash maqsadida e’tirozni eshitmay darsni davom ettirish","Bahsni tartib masalasi deb ko‘rib, savol bergan o‘quvchiga past baho qo‘yish","Sinfga bu e’tirozni baholashni topshirib, xatoni aniqlashni boshqa darsga qoldirish"],"a":0,"e":"Pedagogik takt samimiy, xolis va hurmatli munosabat bilan birga xatoni tan olishni ham qamrab oladi."},{"c":"PM.GEN.08","type":"Y1","k":"mulohaza","d":4,"s":"O‘quvchilar maktab yaqinidagi xavfsiz piyoda yo‘nalishini topish uchun bir hafta kuzatuv o‘tkazishdi. Guruhlar ma’lumotlarni qiyoslab, interaktiv xarita yaratishdi va uni dalillar asosida himoya qilishdi. Darsni tashkil etishning qaysi texnologiyasi ushbu faoliyatning yetakchi belgilarini ifodalaydi?","o":["Muammoli ta’lim — o‘qituvchi bergan savolga bir dars ichida javob topish","Loyihaga asoslangan ta’lim — davomli izlanish orqali amaliy mahsulot yaratish","Evristik ta’lim — yo‘naltiruvchi savollar asosida kichik xulosalar chiqarish","Modulli ta’lim — alohida o‘quv bloklarini izchillikda mustaqil o‘zlashtirish"],"a":1,"e":"Davomli izlanish, real muammo va yakuniy mahsulot loyihaga asoslangan ta’limning tayanch belgilaridir."},{"c":"PM.MET.01","type":"Y1","k":"mulohaza","d":4,"s":"Informatika darsida maqsad nisbiy va mutlaq hujayra havolalarini jadval formulalarida to‘g‘ri qo‘llash edi. Yakuniy baholashda esa o‘qituvchi faqat ikki atamaning ta’rifini so‘radi. Metodik tizimning qaysi elementi maqsadga qayta moslashtirilishi kerak?","o":["Dars sarlavhasi va qo‘llaniladigan prezentatsiya slaydlari soni","Baholash vazifasi — havolani amalda qo‘llashni sinaydigan topshiriq","Fan mazmunidan qat’i nazar, sinfdagi o‘tirish joylarining tartibi","Faqat ta’riflarni qayta yozish uchun ajratilgan vaqtning davomiyligi"],"a":1,"e":"Amaliy qo‘llash maqsadi real jadvalda havola bilan ishlash natijasini tekshirishni talab qiladi."},{"c":"KS.03","type":"Y2","k":"qollash","d":4,"s":"Baholash siklining to‘rtta holatini ularning yetakchi pedagogik vazifasi bilan moslang. Tushunchalar o‘xshash bo‘lishi mumkin, lekin har bir holat uchun faqat bitta vazifa eng maqbul.","left":["Mavzu boshida tayanch bilimni tekshirish","Dars davomida xato bo‘yicha aniq maslahat berish","Natijani bir necha hafta davomida qayta o‘lchash","Bo‘lim oxirida natijani umumiy hisobga olish"],"right":["Summativ xulosa","Davriy monitoring","Rivojlantiruvchi qayta aloqa","Boshlang‘ich diagnostika"],"pairs":[3,2,1,0],"e":"Diagnostika boshlang‘ich holatga, qayta aloqa tuzatish qadamiga, monitoring davriy o‘zgarishga va summativ baholash yakuniy natijaga yo‘naltiriladi."},{"c":"PM.GEN.07","type":"Y2","k":"qollash","d":4,"s":"To‘rtta o‘qituvchi xatti-harakatini ularda ustun bo‘lgan pedagogik qobiliyat bilan moslang. Vaziyatlarda bir nechta qobiliyat qatnashishi mumkin, ammo yetakchi belgi asosida bittadan javob tanlang.","left":["Atamani o‘quvchi yoshiga mos misol bilan tushuntiradi","O‘quvchining hayajonini uning xatti-harakatidan sezadi","Ilmiy maqolalarni o‘qib, fan bilimini doim yangilaydi","Sinf tadbiri uchun rollar va vaqtni muvofiqlashtiradi"],"right":["Akademik qobiliyat","Tashkilotchilik qobiliyati","Perseptiv qobiliyat","Didaktik qobiliyat"],"pairs":[3,2,0,1],"e":"Didaktik tushuntirishga, perseptiv o‘quvchi holatini sezishga, akademik fan bilimiga va tashkilotchilik faoliyatni uyushtirishga tegishli."},{"c":"PM.MET.02","type":"Y2","k":"qollash","d":4,"s":"Informatika darsidagi to‘rtta ishni ularning yetakchi o‘qitish usuli bilan moslang. Faoliyatda AKT ishlatilishi metod turini o‘zi belgilamaydi; asosiy mezon o‘quvchi nimani bajarishidir.","left":["O‘qituvchi dasturning qanday ishlashini ekranda ko‘rsatadi","O‘quvchi yangi dastur yozib, turli qiymatda sinaydi","Ikki algoritmning ishlash vaqtini solishtiradi","Savollar yordamida sabab va oqibatni mustaqil topadi"],"right":["Evristik suhbat","Tahliliy taqqoslash","Amaliy mashq","Namoyish"],"pairs":[3,2,1,0],"e":"Namoyish, amaliy mashq, taqqoslash va evristik suhbat metodlari o‘quvchi hamda o‘qituvchi faoliyatidagi ustuvor harakat bilan farqlanadi."},{"c":"KS.01","type":"Y3","k":"qollash","d":3,"s":"Darsni rejalashtirishda o‘qituvchi fan dasturi, o‘quvchi ehtiyoji va tekshiriladigan natija o‘rtasida izchil bog‘lanish yaratishi kerak. Quyidagi amallarni mantiqiy ketma-ketlikda joylashtiring.","steps":["O‘quvchilarning tayanch bilimi va ehtiyojlarini aniqlash","Aniq va tekshiriladigan o‘quv natijasini belgilash","Maqsadga mos faoliyat va yordam vositasini tanlash","Natijani qanday dalil bilan tekshirishni rejalashtirish"],"display":[2,0,3,1],"e":"Boshlang‘ich holat → natija → faoliyat → tekshiruv dalili tartibi izchil dars rejasini yaratadi."},{"c":"PM.GEN.05","type":"Y3","k":"qollash","d":4,"s":"Sinf rahbari o‘quvchiga yordam berish masalasini oila va fan o‘qituvchilari bilan hal qilmoqchi. U shoshilinch xulosa qilmasdan, muammoni dalillarga asoslanib hal etishi uchun bosqichlarni to‘g‘ri tartibga soling.","steps":["Fanlar va o‘quvchidan kuzatuv dalillarini to‘plash","O‘quvchi va kattalar bilan aniq yordam maqsadini kelishish","Mas’ullar va vaqt belgilangan choralarni bajarish","Natijani kuzatib, yordam rejasini kerak bo‘lsa tuzatish"],"display":[1,3,0,2],"e":"Dalil yig‘ishdan keyin kelishuv, amalga oshirish va kuzatuv asosida takomillashtirish keladi."},{"c":"PM.MET.03","type":"Y3","k":"mulohaza","d":5,"s":"Informatika darsida yangi metod kutilgan natijani barcha o‘quvchilar uchun ta’minlamadi. O‘qituvchi metod samaradorligini taxmin bilan emas, dalillar bilan baholab, keyingi qarorni qabul qilishi kerak. To‘rt qadamni izchil tartiblang.","steps":["Kutiladigan ko‘nikma va kuzatuv mezonini belgilash","O‘quvchilar ishidan mezonga mos dalillarni yig‘ish","Natijani guruhlar kesimida tahlil qilib, sababni aniqlash","Dalilga mos o‘zgarish kiritib, qayta natijani tekshirish"],"display":[2,0,3,1],"e":"Maqsad/mezondan dalilga, so‘ng sabablar tahliliga va natijani qayta baholashga o‘tiladi."}]$bank$::jsonb) LOOP
   v_type:=v->>'type';
   v_ref:='authored:pedagogy-examstyle:20261020:'||(v->>'c')||':'||v_type||':01';
   IF EXISTS (SELECT 1 FROM public.questions WHERE source_reference=v_ref) THEN CONTINUE; END IF;
   SELECT id,group_code INTO STRICT v_construct,v_group FROM public.constructs WHERE code=v->>'c' AND is_active;
   SELECT l.id INTO STRICT v_lesson FROM public.lessons l JOIN public.lesson_constructs lc ON lc.lesson_id=l.id WHERE lc.construct_id=v_construct AND l.status='published'::public.content_status ORDER BY l.created_at LIMIT 1;
   v_q:=gen_random_uuid();
   INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,author_id,is_generated,source_lesson_id,source_reference)
   VALUES(v_q,v_subject,v_construct,v_group,v_type::public.question_format,(v->>'k')::public.cognitive_level,(v->>'d')::int,v->>'s','review'::public.content_status,NULL,false,v_lesson,v_ref);
   v_ids:=ARRAY[]::uuid[];
   IF v_type='Y1' THEN
     FOR i IN 0..3 LOOP v_o:=gen_random_uuid();v_ids:=array_append(v_ids,v_o);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_o,v_q,'a',i,v->'o'->>i);END LOOP;
     v_payload:=jsonb_build_object('correct_option_id',v_ids[(v->>'a')::int+1]);
   ELSIF v_type='Y2' THEN
     FOR i IN 0..3 LOOP v_o:=gen_random_uuid();v_ids:=array_append(v_ids,v_o);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_o,v_q,'a',i+1,v->'left'->>i);END LOOP;
     FOR i IN 0..3 LOOP v_o:=gen_random_uuid();v_ids:=array_append(v_ids,v_o);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_o,v_q,'b',i+1,v->'right'->>i);END LOOP;
     v_pairs:='{}'::jsonb;
     FOR i IN 0..3 LOOP j:=(v->'pairs'->>i)::int;v_pairs:=v_pairs||jsonb_build_object(v_ids[i+1]::text,v_ids[j+5]::text);END LOOP;
     v_payload:=jsonb_build_object('pairs',v_pairs);
   ELSIF v_type='Y3' THEN
     FOR i IN 0..3 LOOP v_ids:=array_append(v_ids,gen_random_uuid());END LOOP;
     FOR i IN 0..3 LOOP j:=(v->'display'->>i)::int;INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_ids[j+1],v_q,'a',i+1,v->'steps'->>j);END LOOP;
     v_payload:=jsonb_build_object('order',to_jsonb(v_ids));
   ELSE RAISE EXCEPTION 'Unknown format %',v_type;END IF;
   INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(v_q,v_payload,v->>'e');
 END LOOP;
 IF (SELECT count(*) FROM public.questions WHERE source_reference LIKE 'authored:pedagogy-examstyle:20261020:%')<>12 THEN RAISE EXCEPTION 'Calibrated review batch count != 12';END IF;
 IF EXISTS (SELECT 1 FROM public.questions q LEFT JOIN public.question_keys k ON k.question_id=q.id WHERE q.source_reference LIKE 'authored:pedagogy-examstyle:20261020:%' AND (q.status<>'review' OR q.source_lesson_id IS NULL OR k.question_id IS NULL)) THEN RAISE EXCEPTION 'Calibrated review batch integrity fail';END IF;
END $calibrate$;
COMMIT;
